function officialDuration(ref: string): number | null {
  if (OFFICIAL_DURATIONS[ref] != null) return OFFICIAL_DURATIONS[ref];
  const unit = ref.split("/")[0];
  return OFFICIAL_DURATIONS[unit] ?? null;
}

// ── entry construction ─────────────────────────────────────────────────────
function buildEntry(
  specKey: string,
  spec: CorpusSpec,
  sessionId: string,
  p: CorpusPaper,
  legacy = false,
): CorpusPaperEntry | null {
  // split dir at the LAST dash: "4CH1-1C" → 4CH1 + 1C; "WMA11-01A" → WMA11 + 01A
  const cut = p.d.lastIndexOf("-");
  if (cut <= 0 || cut === p.d.length - 1) return null;
  const unit = p.d.slice(0, cut);
  const variant = p.d.slice(cut + 1);
  const ref = `${unit}/${variant}`;
  const isIGCSE = spec.qual === "international-gcse";

  // G1 (CIE-INTEGRATION card): CIE QP dirs ("9701-S25-QP-11") need their own
  // parse — the generic last-dash cut yields unit "9701-S25-QP" → title falls
  // to ialUnitTitle's "Unit P" and ref "9701-S25-QP/11". The CIE grammar gives
  // ref "<syllabus>/<component>", title "Paper <n>" (+ the cover-verified
  // paper name when the map holds one), and the variant digit as a chip —
  // matching how the covers themselves name the papers.
  const cie = parseCieDir(p.d);
  if (cie) {
    const tens = Number(cie.component[0]);
    const units = Number(cie.component[1]);
    const paperName = CIE_PAPER_TITLES[`${cie.syllabus}/${tens}`];
    return {
      specKey,
      specTitle: specTitle(spec),
      qual: spec.qual,
      sessionId,
      dir: p.d,
      unit: cie.syllabus,
      variant: cie.component,
      ref: `${cie.syllabus}/${cie.component}`,
      title: paperName ? `Paper ${tens} — ${paperName}` : `Paper ${tens}`,
      // D2 (card): the 9709 component-7 rows are the legacy 2016-2019
      // syllabus paper — no modern course claims them (archive-browser-only)
      specBadge:
        cie.syllabus === "9709" && tens === 7 ? "Legacy syllabus" : legacy ? "Legacy spec" : null,
      variantChip: units !== 1 ? `Variant ${units}` : null,
      qpBytes: p.qp,
      msBytes: p.ms,
      erBytes: p.er,
      // G4 posture: no CIE durations are attested in OFFICIAL_DURATIONS —
      // every CIE mock renders the honest editable-estimate state
      durationMin: officialDuration(ref),
      component: tens,
      qpPath: p.qp != null ? corpusRawPath(specKey, sessionId, p.d, "qp.pdf") : "",
      msPath: p.ms != null ? corpusRawPath(specKey, sessionId, p.d, "ms.pdf") : "",
      erPath: p.er != null ? corpusRawPath(specKey, sessionId, p.d, "er.pdf") : "",
    };
  }

  let title: string;
  let variantChip: string | null = null;
  if (isIGCSE) {
    title = `Paper ${variant}`;
    // "1CR" → Timezone R (SME wording); "1C" → no chip
    const tz = variant.match(/^(\d+[A-Z])R$/);
    if (tz) {
      title = `Paper ${tz[1]}`;
      variantChip = "Timezone R";
    }
  } else {
    title = ialUnitTitle(unit);
    const v = variant.match(/^0\d([A-Z])$/);
    if (v) variantChip = `Variant ${v[1]}`;
  }

  return {
    specKey,
    specTitle: specTitle(spec),
    qual: spec.qual,
    sessionId,
    dir: p.d,
    unit,
    variant,
    ref,
    title,
    specBadge: legacy ? "Legacy spec" : null,
    variantChip,
    qpBytes: p.qp,
    msBytes: p.ms,
    erBytes: p.er,
    durationMin: officialDuration(ref),
    component: null,
    qpPath: p.qp != null ? corpusRawPath(specKey, sessionId, p.d, "qp.pdf") : "",
    msPath: p.ms != null ? corpusRawPath(specKey, sessionId, p.d, "ms.pdf") : "",
    erPath: p.er != null ? corpusRawPath(specKey, sessionId, p.d, "er.pdf") : "",
  };
}

/**
 * All corpus papers for a course, flattened. Sorted newest session first,
 * then by reference. Papers missing BOTH qp and ms are dropped (nothing to
 * view).
 */
export function corpusPapersForCourse(slug: string): CorpusPaperEntry[] {
  const map = COURSE_SPECS[slug];
  if (!map) return [];
  const out: CorpusPaperEntry[] = [];
  const legacySet = new Set(map.legacySpecs ?? []);
  for (const specKey of [...map.specs, ...(map.legacySpecs ?? [])]) {
    const spec = corpusIndex.specs[specKey];
    if (!spec) continue;
    const legacy = legacySet.has(specKey);
    for (const session of spec.sessions as CorpusSession[]) {
      for (const p of session.papers as CorpusPaper[]) {
        if (p.qp == null && p.ms == null) continue;
        const entry = buildEntry(specKey, spec, session.id, p, legacy);
        if (!entry) continue;
        if (map.units && !map.units.includes(entry.unit)) continue;
        if (map.variants && !map.variants.includes(entry.variant)) continue;
        if (map.components) {
          // CIE component filter (card A3): CIE entries always carry their
          // component (the tens digit); non-CIE entries are null and can
          // never match a components-filtered course (none exists — the
          // filter is CIE-only by construction).
          if (entry.component == null || !map.components.includes(entry.component)) continue;
        }
        if (map.tier) {
          // 4MA1 variants: 1F/2F (foundation), 1H/2H (higher), optional R suffix
          const isH = entry.variant.includes("H");
          const isF = entry.variant.includes("F");
          if (map.tier === "H" && !isH) continue;
          if (map.tier === "F" && !isF) continue;
        }
        out.push(entry);
      }
    }
  }
  return out.sort(
    (a, b) =>
      sessionRankOf(b.sessionId) - sessionRankOf(a.sessionId) ||
      a.ref.localeCompare(b.ref) ||
      a.dir.localeCompare(b.dir),
  );
}

/** True when the corpus holds at least one mapped paper for this course. */
export function courseHasCorpusPapers(slug: string): boolean {
  return corpusPapersForCourse(slug).length > 0;
}

export function findCorpusPaper(
  slug: string,
  sessionId: string,
  dir: string,
): CorpusPaperEntry | null {
  return corpusPapersForCourse(slug).find((p) => p.sessionId === sessionId && p.dir === dir) ?? null;
}

// ── corpus-wide archive (every spec, mapped or not) ────────────────────────
/**
 * The per-course map above is the primary IA, but the corpus holds far more
 * specifications than the hub has courses for: ALL of Cambridge International,
 * IAL accounting / business / economics / IT / law / psychology, legacy GCE
 * modular maths, IGCSE commerce / computer science / human biology / English
 * Language B — 3,232 of 5,281 papers across 44 specs were unreachable from
 * the UI (operator report, trace 1a140bd78ea3e419). The archive browser
 * (app/past-papers) surfaces every spec below, so nothing in the corpus is
 * hidden behind the course catalog again.
 */
export interface CorpusArchiveSpec {
  specKey: string;
  spec: CorpusSpec;
  /** first hub course (alphabetical) whose primary spec list includes this spec */
  courseSlug: string | null;
  /** paper dirs holding at least one of qp/ms (same drop rule as course pages) */
  paperCount: number;
  sessionCount: number;
}

const COURSE_FOR_SPEC: Map<string, string> = (() => {
  const m = new Map<string, string>();
  for (const [slug, map] of Object.entries(COURSE_SPECS)) {
    for (const key of map.specs) if (!m.has(key)) m.set(key, slug);
  }
  return m;
})();

export function courseForSpec(specKey: string): string | null {
  return COURSE_FOR_SPEC.get(specKey) ?? null;
}

export function allArchiveSpecs(): CorpusArchiveSpec[] {
  return Object.entries(corpusIndex.specs)
    .map(([specKey, spec]) => ({
      specKey,
      spec,
      courseSlug: courseForSpec(specKey),
      paperCount: spec.sessions.reduce(
        (n, s) => n + s.papers.filter((p) => p.qp != null || p.ms != null).length,
        0,
      ),
      sessionCount: spec.sessions.length,
    }))
    .sort((a, b) => a.specKey.localeCompare(b.specKey));
}

/** Flattened paper list for ONE spec — the archive browser's per-spec page. */
export function archivePapersForSpec(specKey: string): CorpusPaperEntry[] {
  const spec = corpusIndex.specs[specKey];
  if (!spec) return [];
  const out: CorpusPaperEntry[] = [];
  for (const session of spec.sessions as CorpusSession[]) {
    for (const p of session.papers as CorpusPaper[]) {
      if (p.qp == null && p.ms == null) continue;
      const entry = buildEntry(specKey, spec, session.id, p);
      if (entry) out.push(entry);
    }
  }
  return out.sort(
    (a, b) =>
      sessionRankOf(b.sessionId) - sessionRankOf(a.sessionId) ||
      a.ref.localeCompare(b.ref) ||
      a.dir.localeCompare(b.dir),
  );
}
